"""Apply reviewed wording corrections to the owned reports only.
Run once; source report snapshots are in before/.
"""
from pathlib import Path
import json
P=Path(__file__).resolve().parents[2]
ISSUES={}
def edit(track,changes,issues):
 f=P/track/'report.md';s=(P/'reviews/minor-fixes/before'/(track.replace('/','__')+'.txt')).read_text()
 for old,new in changes:
  assert old in s,(track,old[:100]);s=s.replace(old,new)
 # Historical commands retain the original outcomes. Remove obsolete current-status bullets.
 s='\n'.join(l for l in s.splitlines() if not (l.startswith('- ') and ('report.md was not written' in l or 'report.md is still NOT on disk' in l)))+'\n'
 s+='\n## Response to review\n\nReview: `'+ ('../../reviews/' if track.startswith('primal/') else '../reviews/' if '/' not in track else '../../reviews/') + {'primal/chain':'primal-chain-review-r1.md','primal/dtoc5-lukvle10':'primal-dtoc5-lukvle10-review-r1.md','primal/lnts':'primal-lnts-review-r1.md','primal/powerflow':'primal-powerflow-review-r1.md','primal/water-ann-kan':'primal-water-ann-kan-review-r1.md','audit-ir':'audit-ir-review-r1.md','eg-recheck':'eg-recheck-review-r1.md','scip-bug':'scip-bug-review-r1.md','literature/control':'lit-control-review-r2.md','literature/network':'lit-network-review-r2.md'}[track]+'`. Checked and resolved on 2026-10-03.\n\n'
 s+='| issue | resolution and evidence |\n|---|---|\n'
 for i,title,res,integration in issues:s+=f'| {i}. {title} | {res} |\n'
 check='code/minor_review_check.py' if track=='primal/water-ann-kan' else 'checks/minor_review_check.py' if track.startswith('literature/') else 'minor_review_check.py'
 log='checks/minor_review_check.log' if track.startswith('literature/') else 'logs/minor_review_check.log'
 s+=f'\nTargeted check: `OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 PYTHONDONTWRITEBYTECODE=1 python3 research-20260929/publication/{track}/{check} > research-20260929/publication/{track}/{log}` (from the repository root). Results are in `{log}`. No main computation, solver campaign, project-wide verification or CI check was run for this revision.\n'
 f.write_text(s);ISSUES[track]=issues

